import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor gelu_forward(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void gelu_kernel(const float* __restrict__ Xptr,
                             float* __restrict__ Yptr,
                             int64_t N)
{
  constexpr int VecSize = 4;
  int64_t tid_global    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t total_threads = (int64_t)gridDim.x * blockDim.x;
  const float c0 = 0.7978845608028654f; // sqrt(2/pi)
  const float c1 = 0.044715f;
  int64_t num_vec = N / VecSize;
  const float4* __restrict__ X4 = reinterpret_cast<const float4*>(Xptr);
  float4* __restrict__ Y4 = reinterpret_cast<float4*>(Yptr);
  // Main loop: fully vectorized 128-bit loads/stores, coalesced across threads.
  for (int64_t vidx = tid_global; vidx < num_vec; vidx += total_threads) {
    float4 xv = __ldg(&X4[vidx]);
    float4 yv;
    float x  = xv.x;
    float x3 = x * x * x;
    float t  = tanhf(c0 * (x + c1 * x3));
    yv.x = 0.5f * x * (1.0f + t);
    x  = xv.y;
    x3 = x * x * x;
    t  = tanhf(c0 * (x + c1 * x3));
    yv.y = 0.5f * x * (1.0f + t);
    x  = xv.z;
    x3 = x * x * x;
    t  = tanhf(c0 * (x + c1 * x3));
    yv.z = 0.5f * x * (1.0f + t);
    x  = xv.w;
    x3 = x * x * x;
    t  = tanhf(c0 * (x + c1 * x3));
    yv.w = 0.5f * x * (1.0f + t);
    Y4[vidx] = yv;
  }
  // Tail loop for leftover elements (in case N not divisible by VecSize)
  int64_t tail_start = num_vec * VecSize;
  for (int64_t idx = tail_start + tid_global; idx < N; idx += total_threads) {
    float x  = __ldg(&Xptr[idx]);
    float x3 = x * x * x;
    float t  = tanhf(c0 * (x + c1 * x3));
    Yptr[idx] = 0.5f * x * (1.0f + t);
  }
}

torch::Tensor gelu_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);

  int64_t N = x_c.numel();

  constexpr int VecSize = 4;
  constexpr int Threads  = 256;

  int64_t num_vecs = (N + VecSize - 1) / VecSize;
  int64_t blocks64 = (num_vecs + Threads - 1) / Threads;
  if (blocks64 < 1) blocks64 = 1;
  if (blocks64 > 65535) blocks64 = 65535;

  dim3 block(Threads);
  dim3 grid((unsigned int)blocks64);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  gelu_kernel<<<grid, block, 0, stream>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      N
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "gelu_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

gelu_ext = load_inline(
    name="cute_gelu_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["gelu_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    GELU activation (BERT/GPT-style tanh approximation) implemented with a
    single fused CUDA kernel using CuTe tensors for vectorized load/compute/store.
    """
    def __init__(self) -> None:
        super(ModelNew, self).__init__()
        self._ext = gelu_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.gelu_forward(x)

